'use client';
import {useState} from 'react';
const rows=[['RE-2026-024','€15.800','€9.120','€6.680','42,3%'],['RE-2026-025','€8.450','€5.340','€3.110','36,8%'],['RE-2026-026','€21.200','€10.350','€10.850','51,2%']];
export default function Relatorios(){const [year,setYear]=useState('2026');return <main style={{padding:32,fontFamily:'Arial',maxWidth:1200}}><h1>Relatórios</h1><p>Rentabilidade, faturação, custos e margens.</p><label>Ano <select value={year} onChange={e=>setYear(e.target.value)}><option>2026</option><option>2025</option></select></label><div style={{display:'flex',gap:16,flexWrap:'wrap',margin:'20px 0'}}>{[['Faturação','€45.450'],['Custos','€24.810'],['Lucro','€20.640'],['Margem','45,4%']].map(x=><div key={x[0]} style={{padding:18,border:'1px solid #ddd',borderRadius:12}}>{x[0]}<br/><strong>{x[1]}</strong></div>)}</div><table style={{width:'100%',borderCollapse:'collapse'}}><thead><tr>{['Obra','Venda','Custo','Lucro','Margem'].map(x=><th key={x} align="left" style={{padding:10}}>{x}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={r[0]}>{r.map((x,i)=><td key={i} style={{padding:12,borderBottom:'1px solid #ddd'}}>{x}</td>)}</tr>)}</tbody></table><button onClick={()=>window.print()} style={{marginTop:20,padding:10}}>Imprimir relatório</button></main>}
